I assumed the round 3 file layout. Configs live in spe/evals/configs/<ID>/ (system.md and tools.json), tickets in spe/evals/tasks/tickets/<id>.json, and the mock tool runner at spe/evals/harness/mock_tools.py. I also assumed grade.py takes --answers, --outputs and --selftest. If r03-workflow.js uses other paths, change only the `P` block.

**Gates before launch.** First, I run `python3 -I spe/evals/graders/grade.py --selftest`. The oracle (answers.json fed back as the outputs) must score 50/50 on both label.category and label.priority. Empty outputs and wrong-label outputs must fail. Second, I regrade round 3's saved outputs with the current grade.py as a control. The numbers must match the r03 measured values in spe/prediction-log.md. Third, I launch this script with `dryRun: true`. That runs 3 cells at 1 trial each through the code grader, the peek scan and the Opus judge. I confirm that no trial was voided or errored, and that every trial got both a grade row and a tone row. I also read the real cost per trial and per judged reply from the dry run and pass them in as `estTrialUsd` and `estJudgePerReplyUsd`. If those costs put the full run over $40, the script skips the last trials of trial 5 evenly across B and C2 and logs each skip. If any gate fails, I halt and report a broken grader and do not launch. If all three pass, I commit the script and the gate output as `SPE r04 evaluate (harness): workflow script, gates passed`. Then I launch the full run with the 50 ticket ids and this session's transcriptDir.

```js
// spe/evals/harness/r04-workflow.js
// Full run args:
//   { ticketIds: [50 ids], transcriptDir: '<this session's transcript dir>',
//     estTrialUsd: <from dry run>, estJudgePerReplyUsd: <from dry run>,
//     trialModel: '<value r03 used; defaults to opus because the plan names none>' }
// Dry run: the same args plus dryRun: true.
// The script's return value is the Workflow result, as in r03-workflow.js.

export const meta = {
  name: 'spe-eval-b-vs-c2',
  description: 'SPE eval of config B (12-line prompt, 6 tools) against C2 (12-line prompt, 3 tools plus check_status) on 50 tickets, 5 trials per cell. Code grader first, Opus tone judge second, hard spend cap.',
  phases: [
    { title: 'Setup' },
    { title: 'Trials' },
    { title: 'Code grade' },
    { title: 'Split cells' },
    { title: 'Peek scan' },
    { title: 'Tone judge' },
    { title: 'Metrics' },
    { title: 'Failure analysis' },
    { title: 'Completeness critic' },
    { title: 'Record' },
  ],
};

// ---------- Fixed design from the approved plan ----------
const ROUND = 4;
const RR = `r${String(ROUND).padStart(2, '0')}`;
const CONFIGS = ['B', 'C2'];
const N_TICKETS = 50;
const TRIALS_PER_CELL = 5;
const CAP_USD = 40;

// ---------- Arguments ----------
const A = (typeof args === 'object' && args) || {};
const DRY = A.dryRun === true;
const TRIAL_MODEL = A.trialModel ?? 'opus';
const JUDGE_MODEL = 'opus';
const UTIL_MODEL = 'opus';
const CONCURRENCY = A.concurrency ?? 10;
const EXTRA_PER_CELL = A.extraPerCell ?? 3;
const EXTRA_CAP = A.extraCap ?? 30;
const MAX_VOID_RATE = A.maxVoidRate ?? 0.05;
const CAP = DRY ? (A.dryCapUsd ?? 3) : CAP_USD;
// Unmeasured defaults. Replace them with per-call costs read from the dry run.
const EST = {
  trial: A.estTrialUsd ?? 0.06,
  judgePerReply: A.estJudgePerReplyUsd ?? 0.02,
  util: A.estUtilUsd ?? 0.3,
};
// 2 base grades, 2 extra grades, peek scan, failure analysis, critic, record.
const UTIL_CALLS = 8;

// ---------- Paths ----------
const P = {
  configFiles: (c) => [`spe/evals/configs/${c}/system.md`, `spe/evals/configs/${c}/tools.json`],
  ticket: (t) => `spe/evals/tasks/tickets/${t}.json`,
  mockTools: 'spe/evals/harness/mock_tools.py',
  grader: 'spe/evals/graders/grade.py',
  answers: 'spe/evals/tasks/answers.json',
  judge: 'spe/evals/graders/judge.md',
  runDir: `spe/evals/runs/${RR}`,
  prediction: `spe/predictions/${RR}.yaml`,
  failures: 'spe/failures.md',
};
// Trials must never touch these. Self-reports and transcripts are both checked against this list.
const FORBIDDEN = [
  'spe/evals/graders', 'grade.py', 'judge.md', 'answers.json', 'spe/evals/runs',
  'spe/predictions', 'spe/plans', 'spe/spec', 'prediction-log', 'failures.md', '-workflow.js',
];

// ---------- Schemas ----------
const TRIAL_SCHEMA = {
  type: 'object',
  required: ['ticket_id', 'label', 'reply', 'tool_calls', 'files_opened', 'commands_run'],
  properties: {
    ticket_id: { type: 'string' },
    label: {
      type: 'object',
      required: ['category', 'priority'],
      properties: { category: { type: 'string' }, priority: { type: 'string' } },
    },
    reply: { type: 'string' },
    tool_calls: {
      type: 'array',
      items: { type: 'object', required: ['tool', 'args'], properties: { tool: { type: 'string' }, args: { type: 'object' } } },
    },
    files_opened: { type: 'array', items: { type: 'string' } },
    commands_run: { type: 'array', items: { type: 'string' } },
  },
};
const GRADE_SCHEMA = {
  type: 'object',
  required: ['ok', 'command', 'rows'],
  properties: {
    ok: { type: 'boolean' },
    error: { type: 'string' },
    command: { type: 'string' },
    rows: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial_id', 'category_ok', 'priority_ok'],
        properties: { trial_id: { type: 'string' }, category_ok: { type: 'boolean' }, priority_ok: { type: 'boolean' } },
      },
    },
  },
};
const SCAN_SCHEMA = {
  type: 'object',
  required: ['files_scanned', 'hits'],
  properties: {
    files_scanned: { type: 'integer' },
    hits: { type: 'array', items: { type: 'object', required: ['label', 'evidence'], properties: { label: { type: 'string' }, evidence: { type: 'string' } } } },
  },
};
const JUDGE_SCHEMA = {
  type: 'object',
  required: ['rows'],
  properties: {
    rows: {
      type: 'array',
      items: {
        type: 'object',
        required: ['key', 'pass', 'score', 'reason'],
        properties: { key: { type: 'string' }, pass: { type: 'boolean' }, score: { type: 'number' }, reason: { type: 'string' } },
      },
    },
  },
};
const FAIL_SCHEMA = {
  type: 'object',
  required: ['types'],
  properties: {
    types: {
      type: 'array',
      items: {
        type: 'object',
        required: ['existing_id', 'name', 'kind', 'what', 'how_to_spot', 'seen_in', 'count', 'proposed_fix'],
        properties: {
          existing_id: { type: ['string', 'null'] },
          name: { type: 'string' },
          kind: { type: 'string', enum: ['model', 'prompt', 'tool design', 'grader', 'task'] },
          what: { type: 'string' },
          how_to_spot: { type: 'string' },
          seen_in: { type: 'array', items: { type: 'string' } },
          count: { type: 'integer' },
          proposed_fix: { type: 'string' },
        },
      },
    },
  },
};
const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'gaps'],
  properties: { complete: { type: 'boolean' }, gaps: { type: 'array', items: { type: 'string' } } },
};
const RECORD_SCHEMA = {
  type: 'object',
  required: ['path', 'bytes'],
  properties: { path: { type: 'string' }, bytes: { type: 'integer' } },
};

// ---------- Spend cap ----------
const spend = { reserved: 0, skips: [] };
const usd = (x) => `$${x.toFixed(2)}`;
function reserve(cost, what) {
  if (spend.reserved + cost > CAP) {
    spend.skips.push({ what, cost: +cost.toFixed(3), reservedAtSkip: +spend.reserved.toFixed(2) });
    log(`SKIP ${what}: reserving ${usd(cost)} would cross the ${usd(CAP)} cap (reserved ${usd(spend.reserved)}).`);
    return false;
  }
  spend.reserved += cost;
  return true;
}
function halt(reason, extra = {}) {
  log(`HALT: ${reason}`);
  return { round: ROUND, dryRun: DRY, halted: true, reason, spendReservedUsdEstimate: +spend.reserved.toFixed(2), skips: spend.skips, ...extra };
}

// ---------- Helpers ----------
const keyOf = (t) => `${t.cfg}|${t.ticket}`;
const valid = (t) => Boolean(t.out && !t.voided && !t.error && t.grade);
const bothOk = (t) => t.grade.category_ok && t.grade.priority_ok;
const rate = (xs) => (xs.length ? +(xs.filter(Boolean).length / xs.length).toFixed(3) : null);
const mean = (xs) => (xs.length ? +(xs.reduce((a, b) => a + b, 0) / xs.length).toFixed(2) : null);
function groupBy(xs, f) {
  const m = new Map();
  for (const x of xs) { const k = f(x); if (!m.has(k)) m.set(k, []); m.get(k).push(x); }
  return m;
}
function cellStats(trials) {
  const m = new Map();
  for (const t of trials) {
    if (!valid(t)) continue;
    const s = m.get(keyOf(t)) ?? { cfg: t.cfg, ticket: t.ticket, n: 0, pass: 0 };
    s.n += 1;
    if (bothOk(t)) s.pass += 1;
    m.set(keyOf(t), s);
  }
  return m;
}
function compact(t) {
  return {
    id: t.id, cfg: t.cfg, ticket: t.ticket, k: t.k, kind: t.kind,
    skipped: t.skipped ?? false, error: t.error ?? null,
    voided: t.voided ?? false, voidReason: t.voidReason ?? null,
    label: t.out?.label ?? null, reply: t.out?.reply ?? null,
    tools: t.out?.tool_calls?.map((c) => c.tool) ?? null,
    grade: t.grade ?? null, tone: t.tone ?? null, toneError: t.toneError ?? null,
  };
}
async function runChunks(thunks) {
  const out = [];
  for (let i = 0; i < thunks.length; i += CONCURRENCY) {
    out.push(...(await parallel(thunks.slice(i, i + CONCURRENCY))));
  }
  return out;
}

// ---------- Trials ----------
function trialPrompt(cfg, ticket, id) {
  const [sys, tools] = P.configFiles(cfg);
  return [
    `You are running one trial of a support-ticket agent eval. Trial id: ${id}.`,
    `1. Read ${sys} and ${tools}. From here on, act as the agent they define and follow that prompt exactly.`,
    `2. Read the ticket at ${P.ticket(ticket)}.`,
    `3. Use only the tools listed in ${tools}. To call one, run: python3 -I ${P.mockTools} --config ${cfg} --ticket ${ticket} <tool_name> '<json args>'. Its stdout is the tool result.`,
    `4. Decide the label (category and priority) and write the reply the agent would send to the customer.`,
    `Rules: open only the three files named above. Run no command except the mock tool command. Do not list, search, or browse the repository.`,
    `Put every file you opened in files_opened and every command you ran in commands_run, exactly as run. Put every tool call in tool_calls with its arguments. Opening any other path voids the trial.`,
    `Return ticket_id as "${ticket}".`,
  ].join('\n');
}
function peekReasons(out, cfg, ticket) {
  const allowed = [...P.configFiles(cfg), P.ticket(ticket)];
  const reasons = [];
  for (const f of out.files_opened ?? []) {
    if (!allowed.some((a) => f.endsWith(a))) reasons.push(`opened ${f}`);
  }
  for (const c of out.commands_run ?? []) {
    if (!c.includes(P.mockTools)) reasons.push(`ran non-tool command: ${c}`);
  }
  const blob = JSON.stringify(out);
  for (const f of FORBIDDEN) if (blob.includes(f)) reasons.push(`output mentions forbidden path "${f}"`);
  if (out.ticket_id !== ticket) reasons.push(`ticket_id mismatch: ${out.ticket_id}`);
  return reasons;
}
async function runTrial(s, ph) {
  const id = `${RR}-trial-${s.cfg}-${s.ticket}-t${s.k}`;
  const t = { id, ...s };
  if (!reserve(EST.trial + EST.judgePerReply, id)) return { ...t, skipped: true };
  try {
    t.out = await agent(trialPrompt(s.cfg, s.ticket, id), { label: id, phase: ph, schema: TRIAL_SCHEMA, model: TRIAL_MODEL });
    const reasons = peekReasons(t.out, s.cfg, s.ticket);
    if (reasons.length) {
      t.voided = true;
      t.voidReason = reasons;
      log(`VOID ${id}: ${reasons.join('; ')}`);
    }
  } catch (e) {
    t.error = String(e);
    log(`ERROR ${id}: ${t.error}`);
  }
  return t;
}
const runBatched = (specs, ph) => runChunks(specs.map((s) => () => runTrial(s, ph)));

// ---------- Code grader (code checks first) ----------
async function codeGrade(trials, tag, ph) {
  const gradable = trials.filter((t) => t.out && !t.voided && !t.error);
  const runs = await parallel(CONFIGS.map((cfg) => async () => {
    const rows = gradable
      .filter((t) => t.cfg === cfg)
      .map((t) => ({ trial_id: t.id, ticket_id: t.ticket, category: t.out.label.category, priority: t.out.label.priority }));
    if (!rows.length) return { cfg, ok: true, rows: [] };
    const file = `${P.runDir}/${tag}-${cfg}-outputs.jsonl`;
    try {
      const r = await agent(
        [
          `You run the code grader for SPE round ${ROUND}. Do not grade, fix, or reinterpret any row yourself.`,
          `1. Create ${P.runDir} if needed. Write these rows to ${file}, one JSON object per line, unchanged:`,
          rows.map((x) => JSON.stringify(x)).join('\n'),
          `2. Run: python3 -I ${P.grader} --answers ${P.answers} --outputs ${file}`,
          `3. Return the grader's per-row results exactly as it printed them, plus the command you ran.`,
          `If the command exits non-zero, or its output lacks any trial_id from step 1, set ok to false and put the error text in error.`,
        ].join('\n'),
        { label: `${RR}-grade-${tag}-${cfg}`, phase: ph, schema: GRADE_SCHEMA, model: UTIL_MODEL },
      );
      return { cfg, ...r };
    } catch (e) {
      return { cfg, ok: false, error: String(e), rows: [] };
    }
  }));
  const byId = new Map();
  const errors = [];
  for (const r of runs) {
    if (!r.ok) errors.push(`${r.cfg}: ${r.error ?? 'grader reported failure'}`);
    for (const row of r.rows ?? []) byId.set(row.trial_id, row);
  }
  const missing = [];
  for (const t of gradable) {
    const row = byId.get(t.id);
    if (row) t.grade = { category_ok: row.category_ok, priority_ok: row.priority_ok };
    else missing.push(t.id);
  }
  if (missing.length) errors.push(`${missing.length} trials missing from grader output, e.g. ${missing.slice(0, 3).join(', ')}`);
  return { ok: errors.length === 0, error: errors.join(' | ') };
}

// ---------- Tone judge (only what code cannot check) ----------
async function judgeCell(ts) {
  const { cfg, ticket } = ts[0];
  const keyed = ts.map((t, i) => ({ key: `reply-${i + 1}`, t }));
  try {
    const r = await agent(
      [
        `You are the tone judge for SPE round ${ROUND}. Read the rubric at ${P.judge} and apply it exactly.`,
        `Read the customer ticket at ${P.ticket(ticket)} for context. Do not open any other file.`,
        `Judge only reply tone as the rubric defines it. Do not judge whether the label is correct. Score each reply on its own.`,
        ...keyed.map(({ key, t }) => `--- ${key} ---\n${t.out.reply}`),
        `Return one row per reply key. Keep each reason under 25 words.`,
      ].join('\n'),
      { label: `${RR}-judge-${cfg}-${ticket}`, phase: 'Tone judge', schema: JUDGE_SCHEMA, model: JUDGE_MODEL },
    );
    const rows = new Map(r.rows.map((x) => [x.key, x]));
    for (const { key, t } of keyed) t.tone = rows.get(key) ?? null;
  } catch (e) {
    for (const { t } of keyed) t.toneError = String(e);
  }
}

// ---------- Main ----------
async function main() {
  phase('Setup');
  const ticketIds = A.ticketIds;
  if (!Array.isArray(ticketIds) || ticketIds.length !== N_TICKETS || new Set(ticketIds).size !== N_TICKETS) {
    return halt(`args.ticketIds must list ${N_TICKETS} distinct ticket ids.`);
  }
  if (!DRY && !A.transcriptDir) {
    return halt('args.transcriptDir is required for a full run so trial transcripts can be scanned for peeking.');
  }
  if (!reserve(UTIL_CALLS * EST.util, 'utility reserve')) {
    return halt('The utility reserve alone crosses the cap.');
  }
  const cells = DRY
    ? [{ cfg: 'B', ticket: ticketIds[0] }, { cfg: 'C2', ticket: ticketIds[0] }, { cfg: 'B', ticket: ticketIds[1] }]
    : ticketIds.flatMap((t) => CONFIGS.map((c) => ({ cfg: c, ticket: t })));
  const perCell = DRY ? 1 : TRIALS_PER_CELL;
  log(`${RR}${DRY ? ' DRY RUN' : ''}: ${cells.length} cells x ${perCell} trials. Cap ${usd(CAP)}. Trial model ${TRIAL_MODEL}.`);

  // Trial-number-major order, so a cap hit skips the last trial numbers evenly across both configs.
  phase('Trials');
  const baseSpecs = [];
  for (let k = 1; k <= perCell; k++) for (const c of cells) baseSpecs.push({ ...c, k, kind: 'base' });
  const all = await runBatched(baseSpecs, 'Trials');

  phase('Code grade');
  const g1 = await codeGrade(all, 'base', 'Code grade');
  if (!g1.ok) return halt(`Code grader failed on base trials: ${g1.error}`, { trials: all.map(compact) });

  let extraCount = 0;
  if (!DRY) {
    phase('Split cells');
    const split = [...cellStats(all).values()].filter((s) => s.pass > 0 && s.pass < s.n);
    const extraSpecs = [];
    for (let e = 1; e <= EXTRA_PER_CELL; e++) {
      for (const s of split) {
        if (extraSpecs.length < EXTRA_CAP) extraSpecs.push({ cfg: s.cfg, ticket: s.ticket, k: perCell + e, kind: 'extra' });
      }
    }
    log(`${split.length} split cells. Running ${extraSpecs.length} extra trials (max ${EXTRA_PER_CELL} per cell, ${EXTRA_CAP} total).`);
    if (extraSpecs.length) {
      const extras = await runBatched(extraSpecs, 'Split cells');
      const g2 = await codeGrade(extras, 'extra', 'Split cells');
      if (!g2.ok) return halt(`Code grader failed on extra trials: ${g2.error}`, { trials: [...all, ...extras].map(compact) });
      all.push(...extras);
      extraCount = extras.filter((t) => !t.skipped).length;
    }
  }

  phase('Peek scan');
  let scan = { status: 'skipped', filesScanned: 0, hits: [] };
  if (A.transcriptDir) {
    try {
      const r = await agent(
        [
          `You are the peek scanner for SPE round ${ROUND}. Search every transcript file under ${A.transcriptDir}.`,
          `Consider only subagents whose label starts with "${RR}-trial-".`,
          `Find every tool call (file read, glob, grep, search, or shell command) whose input contains any of these strings: ${FORBIDDEN.map((f) => `"${f}"`).join(', ')}.`,
          `Report each hit with the subagent label and the exact tool input as evidence. Report how many transcript files you scanned.`,
          `Do not open any file outside ${A.transcriptDir}. Do not edit anything.`,
        ].join('\n'),
        { label: `${RR}-peek-scan`, phase: 'Peek scan', schema: SCAN_SCHEMA, model: UTIL_MODEL },
      );
      scan = { status: r.files_scanned > 0 ? 'done' : 'failed', filesScanned: r.files_scanned, hits: r.hits };
    } catch (e) {
      scan = { status: 'failed', error: String(e), filesScanned: 0, hits: [] };
    }
  } else {
    log('No transcriptDir. The peek check uses trial self-reports only.');
  }
  for (const h of scan.hits) {
    const t = all.find((x) => x.id === h.label);
    if (t && !t.voided) {
      t.voided = true;
      t.voidReason = [`transcript: ${h.evidence}`];
      log(`VOID ${t.id}: transcript hit ${h.evidence}`);
    }
  }
  if (scan.status === 'failed') log('Peek scan failed. The results are flagged and must be rescanned at close-out.');
  const attempted = all.filter((t) => !t.skipped);
  const voided = attempted.filter((t) => t.voided);
  log(`Voided ${voided.length} of ${attempted.length} attempted trials.`);
  if (attempted.length && voided.length / attempted.length > MAX_VOID_RATE) {
    return halt(`Void rate ${(voided.length / attempted.length).toFixed(3)} exceeds ${MAX_VOID_RATE}. Possible answer-key leak.`, { scan, trials: all.map(compact) });
  }

  phase('Tone judge');
  const byCell = groupBy(all.filter(valid), keyOf);
  await runChunks([...byCell.values()].map((ts) => () => judgeCell(ts)));

  // Primary metrics use base trials only, so extras on split cells do not bias the comparison with the prediction.
  phase('Metrics');
  const metrics = {};
  for (const cfg of CONFIGS) {
    const b = all.filter((t) => t.cfg === cfg && t.kind === 'base' && valid(t));
    const judged = b.filter((t) => t.tone);
    const stats = [...cellStats(b).values()];
    metrics[cfg] = {
      n_trials: b.length,
      n_planned: cells.filter((c) => c.cfg === cfg).length * perCell,
      category_acc: rate(b.map((t) => t.grade.category_ok)),
      priority_acc: rate(b.map((t) => t.grade.priority_ok)),
      both_acc: rate(b.map(bothOk)),
      cell_all_pass: rate(stats.map((s) => s.pass === s.n)),
      tone_pass: rate(judged.map((t) => t.tone.pass)),
      tone_judged: judged.length,
      check_status_rate: rate(b.map((t) => t.out.tool_calls.some((c) => c.tool === 'check_status'))),
      mean_tool_calls: mean(b.map((t) => t.out.tool_calls.length)),
    };
    log(`${cfg}: ${JSON.stringify(metrics[cfg])}`);
  }
  const statsAll = cellStats(all);
  const splitTable = [...cellStats(all.filter((t) => t.kind === 'base')).values()]
    .filter((s) => s.pass > 0 && s.pass < s.n)
    .map((s) => {
      const a = statsAll.get(`${s.cfg}|${s.ticket}`);
      return { cfg: s.cfg, ticket: s.ticket, base: `${s.pass}/${s.n}`, with_extras: `${a.pass}/${a.n}` };
    });
  const counts = {
    planned_base: baseSpecs.length,
    attempted: attempted.length,
    skipped: all.filter((t) => t.skipped).length,
    errors: all.filter((t) => t.error).length,
    voided: voided.length,
    extras_run: extraCount,
    graded: all.filter(valid).length,
    tone_missing: all.filter((t) => valid(t) && !t.tone).length,
  };
  const spendReservedUsdEstimate = +spend.reserved.toFixed(2);
  log(`Counts: ${JSON.stringify(counts)}. Reserved spend estimate ${usd(spend.reserved)} of ${usd(CAP)}.`);

  if (DRY) {
    log('Dry run complete. Read the per-call cost from this run and pass it as estTrialUsd and estJudgePerReplyUsd.');
    return { round: ROUND, dryRun: true, metrics, counts, scan, spendReservedUsdEstimate, skips: spend.skips, trials: all.map(compact) };
  }

  phase('Failure analysis');
  const fails = all.filter(valid).filter((t) => !bothOk(t) || (t.tone && !t.tone.pass));
  const sample = CONFIGS.flatMap((cfg) => fails.filter((t) => t.cfg === cfg).slice(0, 75)).map((t) => ({
    id: t.id, cfg: t.cfg, ticket: t.ticket, label: t.out.label,
    category_ok: t.grade.category_ok, priority_ok: t.grade.priority_ok,
    tone_pass: t.tone?.pass ?? null, tone_reason: t.tone?.reason ?? null,
    tools: t.out.tool_calls.map((c) => c.tool),
  }));
  let failureTypes = { types: [] };
  try {
    failureTypes = await agent(
      [
        `You are the failure analyst for SPE round ${ROUND}. ${fails.length} trials failed a code check or the tone judge. ${sample.length} are listed below, up to 75 per config.`,
        `You may read ${P.answers} for expected labels, ticket files under spe/evals/tasks/tickets/, and ${P.failures} for existing F-numbered failure types.`,
        `Group the failures into types. Reuse an existing F-number when a type matches, and set existing_id to null for new types.`,
        `If a failure looks like a grader or answer-key bug and not an agent error, use kind "grader" and say why. Do not edit any file.`,
        JSON.stringify(sample),
      ].join('\n'),
      { label: `${RR}-failure-analysis`, phase: 'Failure analysis', schema: FAIL_SCHEMA, model: UTIL_MODEL },
    );
  } catch (e) {
    log(`Failure analysis failed: ${String(e)}`);
  }

  phase('Completeness critic');
  const summary = {
    round: ROUND, configs: CONFIGS, metrics, counts, splitTable,
    scan: { status: scan.status, filesScanned: scan.filesScanned, hits: scan.hits.length },
    skips: spend.skips, spendReservedUsdEstimate, capUsd: CAP,
    failureTypes: failureTypes.types,
  };
  let critic = { complete: false, gaps: ['critic did not run'] };
  try {
    critic = await agent(
      [
        `You are the completeness critic for SPE round ${ROUND}. Read the saved prediction at ${P.prediction} and compare it with the run summary below.`,
        `List every gap: a predicted metric or config with no measured number, an n below plan with no logged reason, a grader check named in the prediction that this run did not perform, judge coverage below the graded count, a failed or skipped peek scan, and any skipped trials.`,
        `Return complete true only when there are no gaps. Do not edit any file.`,
        JSON.stringify(summary),
      ].join('\n'),
      { label: `${RR}-critic`, phase: 'Completeness critic', schema: CRITIC_SCHEMA, model: UTIL_MODEL },
    );
  } catch (e) {
    log(`Critic failed: ${String(e)}`);
  }
  log(`Critic: complete=${critic.complete}. Gaps: ${critic.gaps.join(' | ') || 'none'}`);

  phase('Record');
  try {
    await agent(
      `Write the JSON below, pretty-printed, to ${P.runDir}/summary.json. Create the folder if needed. Write no other file. Do not commit.\n${JSON.stringify({ ...summary, critic })}`,
      { label: `${RR}-record`, phase: 'Record', schema: RECORD_SCHEMA, model: UTIL_MODEL },
    );
  } catch (e) {
    log(`Record failed: ${String(e)}. Write summary.json from the return value at close-out.`);
  }

  return { ...summary, dryRun: false, critic, trials: all.map(compact) };
}

return await main();
